    mergedZone := ZoneInventory{ZoneID: targetZoneID, Items: merged, ItemCount: len(merged)}
    mergedJSON, _ := json.Marshal(mergedZone)
    return ctx.GetStub().PutState("ZONE_"+targetZoneID, mergedJSON)
}
