	}

	// buildTimestampedNote → getCurrentTimestamp → time.Now()
	// The resulting string differs across endorsing peers.
	record.Diagnosis = buildTimestampedNote(newDiagnosis)
	record.LastChecked = ctx.GetStub().GetTxTimestamp().String() // Use deterministic transaction timestamp

	updatedJSON, err := json.Marshal(record)
	if err != nil {
		return err
	}

	return ctx.GetStub().PutState(recordID, updatedJSON)
}
```

#### 11. **Vulnerability Type:** Interprocedural Nondeterminism
