		var product Product
		json.Unmarshal(productJSON, &product)
		product.Price = product.Price * (1 - discountPct/100)

		updatedJSON, _ := json.Marshal(product)
		ctx.GetStub().PutState(productID, updatedJSON)
	}

	return nil
}
```

### Summary
The `BatchRestock`, `GenerateReport`, and `ApplyDiscounts` functions in the `vuln_04_map_iter.go` file are vulnerable to non-deterministic operations due to the non-deterministic iteration order of Go maps. By sorting the keys of the map before iterating, you can ensure deterministic behavior and avoid endorsement mismatches.

