	if err != nil {
		return err
	}

	// Check if the ballot has been updated after reading it
	newBallotJSON, err := ctx.GetStub().GetState(ballotKey)
	if err != nil {
		return fmt.Errorf("failed to read updated ballot for voter %s: %v", voterID, err)
	}
